@Configuration
public class MovimientosS111JobConfig {

    /** B02-USO-FUTURO-05 (WS-B02-DECOM-S111) distinto de 0: S111 dado de baja, no se genera archivo. */
    @Bean
    JobExecutionDecider s111Activo() {
        return (job, step) -> new FlowExecutionStatus(
                job.getExecutionContext().getInt("decomS111") == 0 ? "ACTIVO" : "BAJA");
    }

    @Bean
    Job movimientosS111(JobRepository repo, Step controlB02, Step fechaLote, Step genera) {
        return new JobBuilder("S500P161", repo)
                .start(controlB02)                       // 10010300-ABRO-BASE + 10010400-VALIDA-BASE
                .next(s111Activo())
                    .on("ACTIVO").to(fechaLote)          // 10010500 + 10010600
                        .next(genera)                    // 20100000-PROCESO-ARCHIVO
                .from(s111Activo())
                    .on("BAJA").end("COMPLETED")         // el original termina sin mensaje
                .end()
                .build();
    }
}
