@Component
@StepScope
@RequiredArgsConstructor
public class TefS111Processor implements ItemProcessor<TefB04, RegistroS111> {

    @Value("#{jobExecutionContext['fechaLote']}") private LocalDate lote;
    private final P161Properties props;

    @Override
    public RegistroS111 process(TefB04 t) {
        return (t.medioEntrega() == props.tef().medioEntrega() && lote.equals(t.fechaActualizacion()))
                ? new RegistroS111.Tef(t.tarjeta(), t.numeroTef())
                : null;
    }
}
// El step de TEF corre después del de contratos y escribe al mismo archivo (mismo writer,
// ExecutionContext compartido para el conteo de detalles).

@Bean
Step genera(JobRepository repo, PlatformTransactionManager tx,
            Step contratos, Step tef, Tasklet entregaS111) {
    // Header en el callback del writer, luego contratos, luego TEF y al final trailer y entrega.
    return new StepBuilder("generaDepInicial", repo)
            .flow(new FlowBuilder<Flow>("depInicial").start(contratos).next(tef).build())
            .build();
}

@Bean
FlatFileFooterCallback trailerS111(@Value("#{jobExecutionContext['detalles']}") Long detalles) {
    return w -> w.write(RegistroS111.encode(new RegistroS111.Trailer(detalles)));   // tipo 99
}

/** CLOSE ... WITH SAVE y publicación: Spring Integration deja el archivo donde S111 lo recoge. */
@Bean
IntegrationFlow entregaS111(P161Properties p) {
    return IntegrationFlow.from("depInicialListo")
            .handle(Files.outboundAdapter(new File(p.directorioS111()))
                    .fileNameGenerator(m -> (String) m.getHeaders().get("titulo"))
                    .temporaryFileSuffix(".writing"))          // publicación atómica
            .get();
}
